// =====================================================
// MONTAR MENSAGEM WHATSAPP - MANUTENÇÃO ASTER
// =====================================================

const registros = $input.all();

function numero(valor) {
  if (valor === null || valor === undefined || valor === '') {
    return 'Não informado';
  }

  return Number(valor).toLocaleString('pt-BR');
}

function detalhes(item) {

  const registro = item.json;
  const d = registro.manutencao || {};
  const odo = registro.odometro || {};

  // VEÍCULO
  const placa =
    d.vehicle?.license_plate ||
    registro.placa ||
    'Não informada';

  const marca = d.vehicle?.brand || '';
  const modelo = d.vehicle?.model || '';
  const ano = d.vehicle?.year || '';

  // BOLSÃO
  const bolsao =
    d.vehicle?.group?.name ||
    'Não informado';

  // MANUTENÇÃO
  const servico =
    d.title || 'Manutenção';

  const observacao =
    d.description || 'Não informada';

  const status =
    d.status?.name ||
    registro.status;

  // ODÔMETRO REAL
  const kmAtual =
    odo.odometer_in_km;

  // RECORRÊNCIA
  let recorrencia = 'Não informada';

  if (
    d.recurrence_in_km !== null &&
    d.recurrence_in_km !== undefined
  ) {
    recorrencia =
      `A cada ${numero(d.recurrence_in_km)} km`;
  }
  else if (
    d.recurrence_in_days !== null &&
    d.recurrence_in_days !== undefined
  ) {
    recorrencia =
      `A cada ${numero(d.recurrence_in_days)} dias`;
  }

  // STATUS VISUAL
  let statusVisual = status || 'Não informado';

  if (status === 'DELAYED') {
    statusVisual = `🔴 *Vencido*`;
  }
  else if (status === 'WARNING') {
    statusVisual = `🟠 *Em breve*`;
  }

  // DISTÂNCIA / PRAZO
  let distanciaPrazo = 'Não informado';

  if (
    d.status?.km !== null &&
    d.status?.km !== undefined
  ) {

    const km = Math.abs(Number(d.status.km));

    distanciaPrazo =
      status === 'DELAYED'
        ? `Vencido há: *${numero(km)} km*`
        : `Faltam: *${numero(km)} km*`;
  }
  else if (
    d.status?.days !== null &&
    d.status?.days !== undefined
  ) {

    const dias = Math.abs(Number(d.status.days));

    distanciaPrazo =
      status === 'DELAYED'
        ? `Vencido há: *${numero(dias)} dia(s)*`
        : `Faltam: *${numero(dias)} dia(s)*`;
  }

  // LIMITE
  let limite = '';

  if (
    d.next_occurrence_in_km !== null &&
    d.next_occurrence_in_km !== undefined
  ) {
    limite =
      `Limite: *${numero(d.next_occurrence_in_km)} km*`;
  }
  else if (d.next_occurrence_date) {

    const data = new Date(d.next_occurrence_date);

    limite =
      `Data limite: *${data.toLocaleDateString('pt-BR')}*`;
  }

  // AÇÃO
  const acao =
    status === 'DELAYED'
      ? `🚨 *AÇÃO NECESSÁRIA*\nProvidenciar a manutenção com prioridade.`
      : `⚠️ *AÇÃO NECESSÁRIA*\nProgramar a manutenção antes de atingir o limite.`;

  // MENSAGEM
  return `📍 *BOLSÃO: ${bolsao.toUpperCase()}*

🚗 *VEÍCULO*
Placa: *${placa}*
Modelo: ${marca} ${modelo}${ano ? ` - ${ano}` : ''}

🔧 *MANUTENÇÃO*
Serviço: ${servico}
Observação: ${observacao}
Recorrência: ${recorrencia}

📊 *SITUAÇÃO*
Status: ${statusVisual}
${distanciaPrazo}
KM atual: *${numero(kmAtual)} km*
${limite}

${acao}`;
}


// =====================================================
// CLASSIFICA OS ALERTAS
// =====================================================

const vencidos = registros.filter(item => {
  const status =
    item.json.manutencao?.status?.name ||
    item.json.status;

  return status === 'DELAYED';
});

const emBreve = registros.filter(item => {
  const status =
    item.json.manutencao?.status?.name ||
    item.json.status;

  return status === 'WARNING';
});


// Se não houver alerta, não gera mensagem
if (vencidos.length === 0 && emBreve.length === 0) {
  return [];
}


// Vencidos aparecem primeiro
const alertasOrdenados = [
  ...vencidos,
  ...emBreve
];


// =====================================================
// MONTA UMA ÚNICA MENSAGEM
// =====================================================

const mensagem = alertasOrdenados
  .map(item => detalhes(item))
  .join('\n\n━━━━━━━━━━━━━━\n\n');

// =====================================================
// OUTPUT
// =====================================================

return [{
  json: {
    total_alertas: alertasOrdenados.length,
    total_vencidos: vencidos.length,
    total_em_breve: emBreve.length,
    mensagem
  }
}];
